import suppliers from "./suppliers.json";

/** The simulated suppliers of the testnet deployment. */
export type SupplierRole = "dataIndexer" | "listOracle" | "computeBasic" | "computeDeep";

/**
 * Public EVM address of each supplier, lowercase. The file is generated by the owner CLI
 * (`bun run owner suppliers-json` in engine) from the owner's keystore; do not edit it by hand.
 */
export const SUPPLIERS = suppliers as Record<SupplierRole, `0x${string}`>;

/** How each supplier is shown to people. */
export const SUPPLIER_NAMES: Record<SupplierRole, string> = {
  dataIndexer: "Data indexer",
  listOracle: "List oracle",
  computeBasic: "Basic compute",
  computeDeep: "Deep compute",
};
